<template><main class="login-page"><div class="login-brand"><span class="mesh-dot"/>TunnelMesh</div><el-card class="login"><div class="locale"><el-button link @click="switchLocale">{{preferences.locale==='zh-CN'?'English':'简体中文'}}</el-button></div><h1>{{t('auth.welcome')}}</h1><p>{{t('auth.description')}}</p><el-form label-position="top" @submit.prevent="submit"><el-form-item :label="t('auth.username')"><el-input v-model="username" autocomplete="username"/></el-form-item><el-form-item :label="t('auth.password')"><el-input v-model="password" type="password" show-password autocomplete="current-password"/></el-form-item><el-button class="submit" type="primary" native-type="submit" :loading="loading">{{t('auth.signIn')}}</el-button><el-alert v-if="error" type="error" :title="t('auth.failed')" show-icon/></el-form></el-card></main></template>
<script setup lang="ts">import{ref}from'vue';import{useI18n}from'vue-i18n';import{useRouter}from'vue-router';import{useAuthStore}from'../stores/auth';import{usePreferencesStore}from'../stores/preferences';const{t}=useI18n(),username=ref(''),password=ref(''),error=ref(false),loading=ref(false),router=useRouter(),auth=useAuthStore(),preferences=usePreferencesStore();function switchLocale(){preferences.setLocale(preferences.locale==='zh-CN'?'en-US':'zh-CN')}async function submit(){loading.value=true;error.value=false;try{await auth.login(username.value,password.value);router.push('/')}catch{error.value=true}finally{loading.value=false}}</script>
<style scoped>.login-page{min-height:100vh;display:grid;place-items:center;padding:24px;background:radial-gradient(circle at 20% 10%,#e8f3ff 0,transparent 35%),var(--tm-bg)}.login-brand{position:fixed;top:28px;left:32px;font-weight:750}.mesh-dot{display:inline-block;width:10px;height:10px;margin-right:8px;border-radius:50%;background:var(--tm-primary);box-shadow:16px 0 0 #8dc5ff}.login{width:min(420px,100%);border:1px solid var(--tm-border);border-radius:10px}.login h1{margin:0;font-size:26px}.login p{margin:6px 0 24px;color:var(--tm-muted)}.locale{text-align:right}.submit{width:100%;margin-bottom:14px}</style>
